import type { createServiceClient } from '@/lib/supabase/server'

// Each organization has one public link (/serve/<token>) that lists every
// upcoming volunteer shift, so a church shares a single link all season
// instead of a new one for each event. The token arrives with migration 013.

type Admin = Awaited<ReturnType<typeof createServiceClient>>

export type VolunteerOrg = { id: string; name: string; timezone?: string | null }

/** Tokens are 32 hex characters, as generated by the database. */
export function isVolunteerToken(token: unknown): token is string {
  return typeof token === 'string' && /^[0-9a-f]{32}$/.test(token)
}

export async function orgByVolunteerToken(admin: Admin, token: string): Promise<VolunteerOrg | null> {
  if (!isVolunteerToken(token)) return null
  const { data, error } = await admin.from('organizations').select('*').eq('volunteer_token', token).maybeSingle()
  if (error || !data) return null
  return data as VolunteerOrg
}

/** The church-wide link, or null until migration 013 has given the organization a token. */
export function volunteerLinkFor(org: { volunteer_token?: string | null } | null | undefined, appUrl: string): string | null {
  return isVolunteerToken(org?.volunteer_token) ? `${appUrl}/serve/${org!.volunteer_token}` : null
}

/** How far ahead the church-wide page lists events. */
export const SERVE_DAYS_AHEAD = 120

/** Most shifts one person can take in a single sign-up from the church-wide link. */
export const MAX_SHIFTS_PER_SIGNUP = 12
